-- รัน SQL นี้ใน Supabase Dashboard → SQL Editor
-- คลิก "New query" แล้ว Paste ทั้งหมด แล้วกด "Run"
-- ======================================================

-- 1. สร้างตาราง posts
CREATE TABLE IF NOT EXISTS posts (
  id          SERIAL PRIMARY KEY,
  image       TEXT NOT NULL,
  category    TEXT NOT NULL,
  title       TEXT NOT NULL,
  description TEXT NOT NULL,
  author      TEXT NOT NULL DEFAULT 'Thompson P.',
  date        TIMESTAMPTZ NOT NULL,
  likes       INTEGER DEFAULT 0,
  content     TEXT NOT NULL
);

-- 2. เปิด RLS (Row Level Security) แต่อนุญาตให้ทุกคนอ่านได้
ALTER TABLE posts ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public read access"
  ON posts FOR SELECT
  USING (true);

-- 3. Seed ข้อมูล 30 โพสต์

-- 4. Reset sequence ให้ auto-increment ต่อจาก id 30
SELECT setval('posts_id_seq', 30);
